/*
 * Floating surface and overlay rules, including the overlay that extends into
 * the titlebar.
 * The fallbacks are the token values.
 */

.floatingSurface {
  --ck-floating-panel-inset: calc(var(--spacing) * 1.5);
  --ck-floating-panel-radius: calc(
    var(--radius-token-composer-single-line, calc(var(--spacing) * 5.5)) +
      var(--ck-floating-panel-inset)
  );

  border-radius: var(--ck-floating-panel-radius);
}

.singleLineSurface {
  --ck-floating-panel-radius: var(
    --radius-token-composer-single-line,
    calc(var(--spacing) * 5.5)
  );

  border-radius: var(--ck-floating-panel-radius);
}

.canvasSurface {
  --ck-floating-panel-radius: var(--radius-base-2xl, 1rem);
}

.composerRadius {
  --ck-floating-panel-radius: var(
    --ck-compose-radius,
    calc(var(--spacing) * 5.5)
  );

  border-radius: var(--ck-floating-panel-radius);
  corner-shape: var(--ck-compose-corner-shape, round);
}

.floatingComposerInset {
  padding-inline: var(--ck-floating-panel-inset);
  padding-bottom: var(--ck-floating-panel-inset);
}

.islandElevation {
  box-shadow: var(--elevation-prominent);
}

.viewerElevation {
  box-shadow: var(--shadow-sidebar-panel);
}

.noDrag {
  -webkit-app-region: no-drag;
}

.extendsIntoTitlebar {
  top: calc(
    -1 *
      var(
        --ck-shell-header-height,
        var(--ck-shell-titlebar-height, var(--height-bar))
      )
  );
}

.overlay {
  top: anchor(top);
  right: anchor(right);
  bottom: anchor(bottom);
  left: anchor(left);
}

.overlay::backdrop {
  -webkit-app-region: initial;
}

:global([aria-hidden="true"]) .overlay {
  visibility: hidden;
}

/*
 * Side panel: slides on the inline axis by its own width. The component
 * animates x with a spring (stiffness 400, damping 40), duration 0
 * under reduced motion; the display switches off when the exit completes.
 */
.sidePanel {
  --side-panel-offset: 100%;

  transform: translateX(var(--side-panel-offset));
  transition: transform var(--side-panel-duration) var(--side-panel-easing);
}

.sidePanel[data-side="start"] {
  --side-panel-offset: -100%;
}

:global([dir="rtl"]) .sidePanel {
  --side-panel-offset: -100%;
}

:global([dir="rtl"]) .sidePanel[data-side="start"] {
  --side-panel-offset: 100%;
}

.sidePanel[data-state="open"] {
  transform: translateX(0);
}

.sidePanel[data-state="closed"][data-hidden="true"] {
  display: none;
}

.sidePanel[data-ck-reduced-motion="true"] {
  transition-duration: 0s;
}

@starting-style {
  .sidePanel[data-state="open"]:not([data-skip-enter]) {
    transform: translateX(var(--side-panel-offset));
  }
}

/*
 * Split-view sizing: drawer width, ratio helpers, bounds and layout.
 */

export const HANDLE_WIDTH = 14;
export const MIN_PANE_WIDTH = 156;
export const DEFAULT_LEFT_RATIO = 0.5;
export const KEYBOARD_STEP = 12;
export const DRAWER_BREAKPOINT = 736;
export const RIGHT_FADE_IN_DELAY_MS = 160;
const DRAWER_MAX_RATIO = 0.9;

export const nonNegative = (value: number) => Math.max(0, value);

export const clampRatio = (value: number) => Math.min(Math.max(value, 0), 1);

export const clampTo = (value: number, max: number) =>
  Math.min(Math.max(value, 0), max);

export const ratioFromPercent = (percent: number | undefined) =>
  percent === undefined ? DEFAULT_LEFT_RATIO : clampRatio(percent / 100);

export const ratioOf = (container: number, left: number) =>
  container === 0 ? 0 : clampRatio(left / container);

export const maxLeftWidth = (
  container: number,
  minLeft: number,
  minRight: number
) => {
  const width = nonNegative(container);
  const room = width - minRight;

  return room <= minLeft ? Math.max(0, width) : Math.max(minLeft, room);
};

export const boundLeftWidth = (
  left: number,
  container: number,
  minLeft: number,
  minRight: number
) => {
  const width = nonNegative(container);

  if (width === 0) {
    return 0;
  }

  const lower = Math.min(minLeft, width);
  const upper = maxLeftWidth(container, minLeft, minRight);

  return upper <= lower
    ? Math.max(0, width)
    : Math.min(Math.max(left, lower), upper);
};

export interface PaneLayout {
  boundedLeftRatio: number;
  boundedLeftWidth: number;
  rightWidth: number;
}

export const layoutPanes = (
  container: number,
  minLeft: number,
  minRight: number,
  left: number
): PaneLayout => {
  const width = nonNegative(container);
  const boundedLeftWidth = boundLeftWidth(left, container, minLeft, minRight);

  return {
    boundedLeftRatio: ratioOf(width, boundedLeftWidth),
    boundedLeftWidth,
    rightWidth: clampTo(Math.max(0, width - boundedLeftWidth), width),
  };
};

export const drawerWidth = (
  container: number,
  minWidth: number,
  maxWidth: number | undefined,
  visibleInset: number
) => {
  const lower = Math.min(minWidth, container);

  const upper = Math.min(
    maxWidth ?? container,
    Math.max(0, container - visibleInset)
  );

  const preferred = Math.min(container * DRAWER_MAX_RATIO, upper);

  return Math.min(container, Math.max(lower, preferred));
};

/* A critically damped spring sampled into a CSS linear easing. */

const STIFFNESS = 380;
const DAMPING = 38;
const MASS = DAMPING ** 2 / (4 * STIFFNESS);
const SAMPLES = 48;
const SETTLED_FRACTION = 0.001;

const omega = Math.sqrt(STIFFNESS / MASS);

const remaining = (seconds: number) =>
  (1 + omega * seconds) * Math.exp(-omega * seconds);

const settleSeconds = () => {
  let seconds = 0;

  while (remaining(seconds) > SETTLED_FRACTION) {
    seconds += 0.01;
  }

  return seconds;
};

const stops = (duration: number) =>
  Array.from({ length: SAMPLES + 1 }, (_, index) =>
    index === SAMPLES
      ? 1
      : Number((1 - remaining((duration * index) / SAMPLES)).toFixed(4))
  );

if (DAMPING !== 2 * Math.sqrt(STIFFNESS * MASS)) {
  throw new Error(
    "The panel motion calculation does not accept critical damping."
  );
}

const SIDE_PANEL_SPRING_SECONDS = settleSeconds();

const SIDE_PANEL_SPRING_EASING = `linear(${stops(SIDE_PANEL_SPRING_SECONDS).join(", ")})`;

export { SIDE_PANEL_SPRING_EASING, SIDE_PANEL_SPRING_SECONDS };

"use client";

/* oxlint-disable shadcn/no-inline-styles, shadcn/no-arbitrary-values, shadcn/no-restyle -- FloatingSurface, PanelHeader and the side panel set CSS custom properties for the spring, use theme-length classes and put classes on their Button. */

import {
  SIDE_PANEL_SPRING_EASING,
  SIDE_PANEL_SPRING_SECONDS,
} from "@/components/panes/spring";
import { Button } from "@/components/ui/button";
import { useReducedMotion } from "@/lib/reduced-motion";
import { cn } from "@/lib/utils";
import { X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import type {
  ComponentProps,
  CSSProperties,
  ReactNode,
  TransitionEvent as ReactTransitionEvent,
} from "react";

import styles from "@/components/panes/panes.module.css";

type FloatingSurfaceVariant =
  | "canvas"
  | "default"
  | "island"
  | "notice"
  | "single-line"
  | "viewer";

type FloatingSurfaceRadius = "composer";

interface FloatingSurfaceClassOptions {
  radius?: FloatingSurfaceRadius;
  unstyled?: boolean;
  variant?: FloatingSurfaceVariant;
}

const isSolidVariant = (variant: FloatingSurfaceVariant) =>
  variant === "island" || variant === "viewer";

const solidSurfaceClasses = (
  variant: FloatingSurfaceVariant,
  radius: FloatingSurfaceRadius | undefined
) => [
  radius !== "composer" && "rounded-2xl",
  variant === "viewer"
    ? cn("bg-fill-viewer-control backdrop-blur-xl", styles.viewerElevation)
    : cn("bg-panel-elevated-secondary", styles.islandElevation),
];

const layeredSurfaceClasses = (variant: FloatingSurfaceVariant) => [
  styles.floatingSurface,
  (variant === "single-line" || variant === "notice") &&
    styles.singleLineSurface,
  variant === "canvas" && styles.canvasSurface,
  variant === "canvas" ? "bg-panel-canvas" : "bg-panel-elevated-secondary",
  "ring-[0.5px] ring-border",
  variant === "notice" ? "shadow-(--shadow-subtle)" : "shadow-2xl",
];

const floatingSurfaceClassName = ({
  radius,
  unstyled = false,
  variant = "default",
}: FloatingSurfaceClassOptions = {}) =>
  cn(
    !unstyled &&
      (isSolidVariant(variant)
        ? solidSurfaceClasses(variant, radius)
        : layeredSurfaceClasses(variant)),
    !unstyled && radius === "composer" && styles.composerRadius
  );

interface FloatingSurfaceProps
  extends ComponentProps<"div">, FloatingSurfaceClassOptions {}

const FloatingSurface = ({
  className,
  radius,
  unstyled,
  variant,
  ...props
}: FloatingSurfaceProps) => (
  <div
    {...props}
    className={cn(
      floatingSurfaceClassName({ radius, unstyled, variant }),
      className
    )}
  />
);

const FloatingComposerInset = ({
  className,
  ...props
}: ComponentProps<"div">) => (
  <div {...props} className={cn(styles.floatingComposerInset, className)} />
);

interface PanelHeaderProps {
  actions?: ReactNode;
  closeDisabled?: boolean;
  closeLabel: string;
  leading?: ReactNode;
  onClose: () => void;
  title: ReactNode;
  titleId?: string;
}

const PanelHeader = ({
  actions,
  closeDisabled,
  closeLabel,
  leading,
  onClose,
  title,
  titleId,
}: PanelHeaderProps) => (
  <div className="flex h-11 shrink-0 items-center justify-between gap-2 py-1 ps-4 pe-2">
    {leading}
    <h2 className="min-w-0 flex-1 truncate" id={titleId}>
      <span className="text-base font-semibold text-text select-none">
        {title}
      </span>
    </h2>
    {actions}
    <Button
      aria-label={closeLabel}
      color="secondary"
      disabled={closeDisabled}
      onClick={onClose}
      radius="full"
      size="toolbar"
      uniform
    >
      <X />
    </Button>
  </div>
);

type SidePanelSide = "end" | "start";

interface SidePanelProps {
  busy?: boolean;
  children?: ReactNode;
  className?: string;
  height?: "content" | "full";
  initial?: boolean;
  label: string;
  onExitComplete?: () => void;
  open: boolean;
  preserveContent?: boolean;
  side?: SidePanelSide;
  size?: "compact" | "default";
}

// oxlint-disable-next-line anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion -- SAFETY: both keys are `--name` custom properties with string values, which React accepts in a style object; CSSProperties has no index for them.
const springStyle = {
  "--side-panel-duration": `${SIDE_PANEL_SPRING_SECONDS}s`,
  "--side-panel-easing": SIDE_PANEL_SPRING_EASING,
} as CSSProperties;

const SidePanel = ({
  busy,
  children,
  className,
  height = "full",
  initial = true,
  label,
  onExitComplete,
  open,
  preserveContent = false,
  side = "end",
  size = "default",
}: SidePanelProps) => {
  const reducedMotion = useReducedMotion();
  const wasOpen = useRef(open);
  const [previousOpen, setPreviousOpen] = useState(open);
  const [exited, setExited] = useState(!open);
  const [skipEnter, setSkipEnter] = useState(!initial && open);

  if (previousOpen !== open) {
    setPreviousOpen(open);
    setSkipEnter(false);

    if (open) {
      setExited(false);
    }
  }

  const hidden = !open && (reducedMotion || exited);

  useEffect(() => {
    if (open) {
      wasOpen.current = true;

      return;
    }

    if (wasOpen.current && reducedMotion) {
      wasOpen.current = false;
      onExitComplete?.();
    }
  }, [onExitComplete, open, reducedMotion]);

  if (hidden && !preserveContent) {
    return null;
  }

  const handleTransitionEnd = (event: ReactTransitionEvent<HTMLDivElement>) => {
    if (
      open ||
      event.target !== event.currentTarget ||
      event.propertyName !== "transform"
    ) {
      return;
    }

    wasOpen.current = false;
    setExited(true);
    onExitComplete?.();
  };

  return (
    <div
      aria-hidden={!open}
      className={cn(
        "z-40 col-start-1 row-start-1 flex h-full max-h-full min-h-0 max-w-full shrink-0 p-2 pt-px",
        height === "content" && "items-start",
        side === "start" &&
          "ps-[calc(var(--spacing)*2+var(--ck-viewer-header-start-inset,0px))]",
        styles.sidePanel
      )}
      data-hidden={hidden}
      data-ck-reduced-motion={reducedMotion}
      data-side={side}
      data-skip-enter={skipEnter ? "" : undefined}
      data-state={open ? "open" : "closed"}
      inert={!open}
      onTransitionEnd={handleTransitionEnd}
      style={springStyle}
    >
      <aside
        aria-busy={busy}
        aria-label={label}
        className={cn(
          floatingSurfaceClassName({ variant: "viewer" }),
          "flex max-h-full min-h-0 max-w-full flex-col text-text",
          height === "content" ? "overflow-y-auto" : "overflow-hidden",
          size === "compact" ? "w-74" : "w-80",
          className
        )}
      >
        {height === "content" ? (
          <div className="flex shrink-0 flex-col">{children}</div>
        ) : (
          children
        )}
      </aside>
    </div>
  );
};

export {
  FloatingComposerInset,
  FloatingSurface,
  PanelHeader,
  SidePanel,
  floatingSurfaceClassName,
};

export type {
  FloatingSurfaceProps,
  FloatingSurfaceRadius,
  FloatingSurfaceVariant,
  PanelHeaderProps,
  SidePanelProps,
  SidePanelSide,
};
